def _helper__feedback_from_audit_process_findings(findings: list['ReviewFinding'], out: dict[str, list[str]]) -> None:
    for f in findings:
        if getattr(f, 'severity', None) != 'blocker':
            continue
        tid = getattr(f, 'task_id', None)
        if not tid:
            continue
        out.setdefault(tid, []).append(_helper__feedback_from_audit_build_finding_entry(f))


def _helper__feedback_from_audit_build_finding_entry(f: 'ReviewFinding') -> str:
    parts = [f"- [RED-TEAM {getattr(f, 'severity', 'blocker')}] {getattr(f, 'message', '')}"]
    if getattr(f, 'file', None):
        parts.append(f'  file: {f.file}')
    if getattr(f, 'line', None) is not None:
        parts.append(f'  line: {f.line}')
    if getattr(f, 'suggestion', None):
        parts.append(f'  fix: {f.suggestion}')
    return '\n'.join(parts)


def _helper__feedback_from_audit_process_risks(risks: list['AuditRisk'], out: dict[str, list[str]]) -> None:
    for r in risks:
        if getattr(r, 'severity', None) not in ('Critical', 'High'):
            continue
        tid = getattr(r, 'task_id', None)
        if not tid or tid in out:
            continue
        out.setdefault(tid, []).append(_helper__feedback_from_audit_build_risk_entry(r))


def _helper__feedback_from_audit_build_risk_entry(r: 'AuditRisk') -> str:
    block = f"- [RED-TEAM {getattr(r, 'severity', 'risk')}] {getattr(r, 'description', '')}"
    if getattr(r, 'mitigation', None):
        block += f'\n  fix: {r.mitigation}'
    return block"}

